function createDialog(){if(dialog)return;dialog=el('dialog','hubh-dialog');dialog.id='ai-hub-harness-dialog';dialog.setAttribute('aria-labelledby','ai-hub-harness-title');const head=el('header','hubh-head'),avatar=el('img');avatar.src='/ai-hub/assets/sasha-avatar.png';avatar.alt='Sasha';const title=el('div');const h=el('h2',null,'Sasha · AI Workbench');h.id='ai-hub-harness-title';title.append(h,el('div','hubh-muted','Форк Sasha · на базе Open WebUI'));head.append(avatar,title,btn('✕',()=>dialog.close()));head.lastChild.setAttribute('aria-label','Закрыть');dialog.append(head);const tabs=el('nav','hubh-tabs');tabs.setAttribute('aria-label','Настройки AI Workbench');for(const [id,name]of [['routing','Режим и модели'],['runs','План и память'],['connections','Модели: подключения'],['services','Соцсети и приложения'],['media','Изображения и видео'],['local-modules','Локальные модули'],['catalog','Каталог навыков'],['projects','Проекты и файлы'],['storage','Хранилища и бэкапы']]){const b=btn(name,()=>switchTab(id));b.dataset.tab=id;tabs.append(b);}dialog.append(tabs);notice=el('div','hubh-notice');notice.hidden=true;notice.setAttribute('aria-live','polite');content=el('div','hubh-content');dialog.append(notice,content);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.body.append(dialog);}
export function openHarness(tab='routing'){if(!owner)return;css();createDialog();if(!dialog.open)dialog.showModal();switchTab(tab);}
async function switchTab(tab){cleanupMedia();currentTab=tab;const v=++requestVersion;dialog.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));message('Загрузка…');content.replaceChildren();try{if(tab==='routing')await renderRouting(v);else if(tab==='connections')await renderConnections(v);else if(tab==='services')await renderServices(v);else if(tab==='local-modules')await renderLocalModules({content,api,json,message,isCurrent:()=>v===requestVersion&&dialog?.open});else if(tab==='media')await renderMedia({content,api,json,message,chatId,isCurrent:()=>v===requestVersion&&dialog?.open});else if(tab==='runs')await renderRuns(v);else if(tab==='catalog')await renderCatalog(v);else if(tab==='projects')await renderProjects(v);else await renderStorage(v);if(v===requestVersion)message('');}catch(e){if(v===requestVersion)message(e.message,true);}}
async function renderRouting(v){const [s,m,w]=await Promise.all([api('harness/settings'),api('harness/models'),api('workspace')]);if(v!==requestVersion)return;settings=s.settings||s;modelRows=m.data||[];const form=el('form');form.id='ai-hub-routing-form';const enabled=check(form,'Harness: план, память и контрольные точки',settings.enabled,'enabled');const help=btn('?',()=>{const target=form.querySelector('#ai-hub-harness-help');target.hidden=!target.hidden;help.setAttribute('aria-expanded',String(!target.hidden));},'hubh-help-button');help.id='ai-hub-harness-help-button';help.setAttribute('aria-label','Что означает Harness');help.setAttribute('aria-expanded','false');help.setAttribute('aria-controls','ai-hub-harness-help');enabled.parentElement.append(help);const explanation=el('div','hubh-card');explanation.id='ai-hub-harness-help';explanation.hidden=true;explanation.append(el('h3',null,'Что включает Harness'),el('p',null,'Это режим организации работы агента: сохраняет план, память проекта, контрольные точки и передачу контекста. Выбор модели остаётся ручным или становится автоматическим — по выбранным ниже правилам.'),el('p',null,'Без галочки работает обычный чат выбранной модели. История и подключённый аккаунт сохраняются; дополнительные правила harness не применяются.'),el('p',null,'Как в подходе Hermes, полезные рабочие приёмы можно сохранить как навыки и использовать повторно. Это не обучение весов модели. Сам Hermes — отдельный агент, он не встроен в этот чат.'));form.append(explanation);const grid=el('div','hubh-grid');form.append(grid);const mode=select(grid,'Выбор исполнителя',settings.mode||'manual',[['manual','Вручную — выбранная модель'],['auto','Автоматически — по правилам']],'mode');const complexity=select(grid,'Сложность задачи',settings.complexity||'auto',[['auto','Определять по запросу'],['simple','Простая'],['complex','Сложная']],'complexity');const project=select(grid,'Рабочий проект',settings.project_id||'',[['','Диалог без папки проекта'],...(w.projects||[]).map(p=>[p.id,p.name])],'project_id');const budget=field(grid,'Максимальный бюджет запроса, USD','number',settings.budget_usd,'budget_usd');budget.min='0';budget.step='0.01';const reserve=field(grid,'Сохранять резерв квоты, %','number',settings.reserve_percent??10,'reserve_percent');reserve.min='0';reserve.max='99';const tokens=field(grid,'Порог входного контекста, ≈ токенов','number',settings.max_input_tokens||32000,'max_input_tokens');tokens.min='256';tokens.max='2000000';const models=card('Модели для автоматического выбора','Порядок — предпочтение. Недоступные подключения исключаются. Неизвестная квота не считается свободным ресурсом.');const checks=[];for(const m of modelRows){const c=check(models,m.name+(m.connected?'':' · требуется подключение'),(settings.models||[]).includes(m.id));c.value=m.id;checks.push(c);}if(!checks.length)models.append(el('p','hubh-muted','Пока нет моделей. Подключите провайдера.'));form.append(models);const auto=check(form,'Находить и подключать подходящие расширения из доверенных источников',settings.auto_extensions,'auto_extensions');const trusted=field(form,'Доверенные источники — по одному репозиторию на строку','textarea',(settings.trusted_sources||[]).join('\n'),'trusted_sources');form.append(el('p','hubh-muted','Модели с неизвестной максимальной стоимостью исключаются при заданном USD бюджете. Пустое поле — без ограничения USD. Размер входа оценивается по тексту; это не точный токенизатор и не квота провайдера. Авторежим учитывает подключение, сложность, доступные лимиты, баланс и размер контекста. Смена модели получает сохранённый план и контекст; незавершённые действия требуют проверки.'));const save=btn('Сохранить правила',()=>{} ,'hubh-primary');save.type='submit';form.append(save);form.onsubmit=e=>{e.preventDefault();action(save,async()=>{const next={...settings,enabled:enabled.checked,mode:mode.value,complexity:complexity.value,project_id:project.value,budget_usd:budget.value===''?null:Number(budget.value),reserve_percent:Number(reserve.value),max_input_tokens:Number(tokens.value),models:checks.filter(c=>c.checked).map(c=>c.value),auto_extensions:auto.checked,trusted_sources:trusted.value.split('\n').map(x=>x.trim()).filter(Boolean)};const r=await api('harness/settings',json('PUT',next));settings=r.settings||r;paintMode();message('Правила сохранены. Они применятся к следующему запросу.');});};content.append(form);paintMode();}
function connectionProvider(m){return m.provider==='api'?m.id.replace(/^ai_hub\./,'').split('/')[1]:m.provider;}
async function renderConnections(v){const r=await api('harness/models');if(v!==requestVersion)return;modelRows=r.data||[];connectionRows=r.connections||[];const row=el('div','hubh-row');row.append(el('p','hubh-muted','Учётная запись и API-ключ — разные способы подключения. Ключ передаётся серверу и не сохраняется в браузере.'));content.append(row);const groups=new Map();for(const m of modelRows){const key=connectionProvider(m);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m);}for(const [provider,list]of groups){const connected=list.some(m=>m.connected),c=card(provider,connected?'Подключение настроено':list.find(m=>m.reason)?.reason||'Нужно подключение');c.append(el('p',null,list.map(m=>m.name).join(' · ')));const b=btn(connected?'Проверить / настроить':'Подключить',()=>connectionForm(provider,list));c.append(b);content.append(c);}if(!groups.size)content.append(el('p',null,'Провайдеры пока не обнаружены.'));}
function connectionForm(provider,list){content.replaceChildren();message('');const form=el('form');form.id='ai-hub-connect-form';form.append(el('h3',null,'Подключение · '+provider));const connection=connectionRows.find(c=>c.provider===provider)||{};const methods=connection.auth_methods||[...new Set(list.flatMap(m=>m.auth_methods||[]))];const method=select(form,'Способ подключения',connection.auth_type||methods[0]||'api_key',methods.map(m=>[m,({account:'Войти в аккаунт',api_key:'API-ключ',local:'Локальный сервер'})[m]||m]),'auth_type');const key=field(form,'API-ключ','password','','api_key');key.autocomplete='off';const base=field(form,'Адрес API (если используется свой шлюз)','url',connection.base_url||'','base_url');base.placeholder='https://api.example.com/v1';const instructions=el('div','hubh-card');instructions.hidden=true;form.append(instructions);const draw=()=>{key.parentElement.hidden=method.value!=='api_key';base.parentElement.hidden=method.value==='account';};method.onchange=draw;draw();const row=el('div','hubh-row');for(const [a,t]of [['login','Войти'],['save','Сохранить'],['test','Проверить']]){const b=btn(t,()=>action(b,async()=>{const payload={action:a,auth_type:method.value,...(key.value?{api_key:key.value}:{}),...(base.value?{base_url:base.value}:{})};let r;try{r=await api('harness/connect/'+encodeURIComponent(provider),json('POST',payload));}finally{key.value='';}instructions.hidden=false;instructions.replaceChildren();if(r.instructions)instructions.append(el('p',null,typeof r.instructions==='string'?r.instructions:JSON.stringify(r.instructions)));if(r.auth_url){const u=new URL(r.auth_url,location.origin);if(['https:','http:'].includes(u.protocol)){const link=el('a','hubh-button','Открыть страницу входа');link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';instructions.append(link);}}if(r.user_code)instructions.append(el('code','hubh-code',r.user_code));if(r.ok&&r.status==='connected')instructions.append(btn('Обновить список моделей',()=>location.reload()));message(r.message||r.status||'Готово. Обновите список после завершения подключения.');}));row.append(b);}row.append(btn('К списку',()=>switchTab('connections')));form.append(row);form.onsubmit=e=>e.preventDefault();content.append(form);}
async function renderRuns(v){const r=await api('harness/runs/current?chat_id='+encodeURIComponent(chatId()));if(v!==requestVersion)return;content.replaceChildren();const runs=r.runs||[];for(const run of runs){const c=card(run.title||'Текущая задача',run.status||'');const list=el('ol');for(const step of run.steps||[])list.append(el('li',null,`${['done','completed'].includes(step.status)?'✓':step.status==='running'?'◌':'○'} ${step.title}`));c.append(list);if(run.checkpoint)c.append(el('pre','hubh-code',typeof run.checkpoint==='string'?run.checkpoint:JSON.stringify(run.checkpoint,null,2)));const row=el('div','hubh-row');row.append(btn('Контрольная точка',()=>editRun(run)),btn('Экспорт для другой модели',()=>downloadRun(run)));c.append(row);content.append(c);}if(!runs.length)content.append(el('p','hubh-muted','Для этого диалога пока нет сохранённого плана. Создайте его здесь или включите harness перед новым запросом.'));content.append(btn('+ План задачи',()=>editRun()));const memory=card('Память проекта','Сохранённые решения и проверенные приёмы доступны при продолжении в другой модели.');for(const m of r.memory||[]){const entry=el('div','hubh-card');entry.append(el('p',null,(m.kind?'['+m.kind+'] ':'')+m.text));if(m.kind==='learning'&&m.trusted===false){entry.append(el('span','hubh-badge','Предложение навыка · не установлено'));const promote=btn('Принять как навык',()=>action(promote,async()=>{await api('harness/catalog',json('POST',{id:'learned/'+m.id,auto_enable:true}));message('Навык установлен и подключён к новым запросам.');}));entry.append(promote);}memory.append(entry);}memory.append(btn('+ Сохранить решение / навык',()=>editRun(runs[0]||null,true)));content.append(memory);}
function downloadJSON(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function downloadRun(run){try{const r=await fetch('/ai-hub/api/harness/runs/'+encodeURIComponent(run.id)+'/export',{headers:{Authorization:'Bearer '+localStorage.getItem('token')},credentials:'same-origin'});if(!r.ok)throw Error('Не удалось экспортировать передачу ('+r.status+').');const blob=await r.blob(),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='handoff-'+run.id+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Передача экспортирована с серверным удалением секретов.');}catch(e){message(e.message,true);}}
