export function resolveHarnessModel(id){const key=String(id||'').replace(/^ai_hub\./,'');return nativeAliases.get(key)||modelRows.find(m=>String(m.native_id||'').replace(/^ai_hub\./,'')===key)?.id?.replace(/^ai_hub\./,'')||key;}
